			function setSmsSndngTrgtList() {
			    
			    var dsList = app.lookup("dsList"); // 예약 정보 데이터
			    var dsTrprInfo = app.lookup("dsTrprInfo"); // 대상자 정보 데이터
			    var dsPicList = app.lookup("dsPicList"); // 담당자 정보 데이터
			    
			    var dsSmsSndngTrprList = app.lookup("dsSmsSndngTrprList");
			    dsSmsSndngTrprList.clear();
			    
			    for (var i = 0; i < dsTrprInfo.getRowCount(); i++) {
			        dsSmsSndngTrprList.addRow();
			        dsSmsSndngTrprList.setValue(i, "RCPTN_MBL_TELNO", dsTrprInfo.getValue(i, "MBL_TELNO").toString()); //  test 번호 : 01100000000   
			        //dsSmsSndngTrprList.setValue(i, "RCPTN_MBL_TELNO", "01100000000"); //  test 번호 : 01100000000      
			        dsSmsSndngTrprList.setValue(i, "RCPTN_NM", dsTrprInfo.getValue(i, "TRPR_NM"));
			    }
			    
			    console.log(dsSmsSndngTrprList.getRowDataRanged());
			    
			    var dsSmsSndngPicList = app.lookup("dsSmsSndngPicList");
			    dsSmsSndngPicList.clear();
			    for (var j = 0; j < dsPicList.getRowCount(); j++) {
			        dsSmsSndngPicList.addRow();
			        dsSmsSndngPicList.setValue(j, "RCPTN_MBL_TELNO", dsPicList.getValue(j, "PIC_MBL_TELNO").toString()); //  test 번호 : 01100000000 
			        //dsSmsSndngPicList.setValue(j, "RCPTN_MBL_TELNO", "01100000000"); //  test 번호 : 01100000000    
			        dsSmsSndngPicList.setValue(j, "RCPTN_NM", dsPicList.getValue(j, "PIC_NM"));
			    }
			    
			    console.log(dsSmsSndngPicList.getRowDataRanged());
			}

			/**
			 * 필수 입력사항 체크
			 */
			function validate() {
			    
			    // ### 01. 대상자 목록 예약 대상자 있는 지 체크
			    var dsTrprInfo = app.lookup("dsTrprInfo"); // 대상자목록데이터
			    console.log("대상자목록 = " + dsTrprInfo.getRowCount());
			    if (dsTrprInfo.getRowCount() == 0) {
			        util.Msg.alert(app, "대상자 검색을 하여 예약 대상자를 \n선택해주세요.");
			        return false;
			    }
			    
			    // ### 02. 일정예약 폼 필수 항목 체크
			    if (!util.validate(app, "grpBoardDtl")) return false;
			    
			    // ### 03. 예약시간
			    // 시간 09시 이전 20시 이상 선택시 밸리데이션 체크 > 후 데이터셋에 데이터 set
			    
			    var sHour = app.lookup("cmnTimeCombo2").startTime;
			    var sMinute = app.lookup("cmnTimeCombo2").startMinute;
			    
			    var eHour = app.lookup("cmnTimeCombo2").endTime;
			    var eMinute = app.lookup("cmnTimeCombo2").endMinute;
			    
			    if (sHour == "" || sMinute == "" || eHour == "" || eMinute == "") {
			        util.Msg.alert(app, "예약시간을 선택해주세요.");
			        return false;
			    }
			    
			    if (Number(sHour) < 9 || Number(sHour) > 20) {
			        
			        util.Msg.alert(app, "예약시간은 오전 09시 00분 부터 오후 20시 50분 까지만 선택 하실 수 있습니다.");
			        return false;
			        
			    }
			    
			    if (Number(eHour) < 9 || Number(eHour) > 21) {
			        
			        util.Msg.alert(app, "예약시간은 오전 09시 00분 부터 오후 21시 00분 까지만 선택 하실 수 있습니다.");
			        return false;
			    }
			    
			    if (Number(eHour) == 21) {
			        
			        if (Number(eMinute) > 0) {
			            
			            util.Msg.alert(app, "예약 종료 시간을 21시 선택시 21시 00분 까지만 선택 하실 수 있습니다.");
			            return false;
			            
			        }
			        
			    }
			    
			    util.DataSet.setValue(app, "dsList", 0, "RSVT_BGNG_HR", sHour + sMinute);
			    util.DataSet.setValue(app, "dsList", 0, "RSVT_END_HR", eHour + eMinute);
			    
			    // 01. 예약일이 오늘날짜 이전은 예약 수정 불가 알림창
			    var rsvtBgngYmd = util.DataSet.getValue(app, "dsList", 0, "RSVT_BGNG_YMD").toString();
			    var rsvtBgngHr = util.DataSet.getValue(app, "dsList", 0, "RSVT_BGNG_HR").toString();
			    var rsvtEndHr = util.DataSet.getValue(app, "dsList", 0, "RSVT_END_HR").toString();
			    
			    //    rsvtBgngYmd = "20221111";
			    //    rsvtBgngHr = "1130";
			    //    rsvtEndHr = "1230";
			    //    
			    //    time = "1100";
			    
			    if (viewType == "CREATE") {
			        if (rsvtBgngYmd == date && Number(rsvtEndHr) < Number(time)) {
			            
			            util.Msg.alert(app, "당일 예약시간이 지난 예약은 \n등록 하실 수 없습니다.");
			            return false;
			        }
			    } else if (viewType == "UPDATE") {
			        
			        if (Number(rsvtBgngYmd) < Number(date)) {
			            
			            util.Msg.alert(app, "예약일이 지난 예약은 \n저장(수정) 하실 수 없습니다.");
			            return false;
			        }
			        
			        // 수정시 체크
			        // 02. 예약일이 오늘날짜이고 예약시간이 지난 건은 수정 불가
			        if (rsvtBgngYmd == date && Number(rsvtEndHr) < Number(time)) {
			            
			            util.Msg.alert(app, "당일 예약일시가 지난 예약은 \n저장(수정) 하실 수 없습니다.");
			            return false;
			        } else if (rsvtBgngYmd == date && Number(rsvtEndHr) >= Number(time)) {
			            
			            if (Number(rsvtBgngHr) < Number(time)) {
			                util.Msg.alert(app, "당일 예약일시가 지난 예약은 \n저장(수정) 하실 수 없습니다.");
			                return false;
			            }
			            
			        }
			        
			    }
			    
			    // 03. 수정시 기존 예약건 예약취소상태로 변경
			    
			    // 04. 신규 예약건으로 재 등록 처리
			    
			    // 05. 문자발송 > 예약문자발송일시 현재시간과 예약발송 시간 비교 5분전 발송 불가 5분 이상 발송
			    
			    // ### 04. 예약문자발송여부 Y 인 경우 예약발송시간 입력 체크
			    var dsList = app.lookup("dsList"); // 예약 정보 데이터
			    
			    var rsvtChrctrSndngYmd = dsList.getValue(0, "RSVT_CHRCTR_SNDNG_YMD").toString();
			    var rsvtChrctrSndngHr = dsList.getValue(0, "RSVT_CHRCTR_SNDNG_HR").toString();
			    
			    //rsvtChrctrSndngYmd = "20221109";
			    //rsvtChrctrSndngHr = "1746";
			    
			    console.log("예약문자발송여부 ===== " + dsList.getValue(0, "RSVT_CHRCTR_SNDNG_YN").toString());
			    if (dsList.getValue(0, "RSVT_CHRCTR_SNDNG_YN").toString() == "Y") {
			        
			        if (rsvtChrctrSndngHr == "") {
			            util.Msg.alert(app, "예약문자발송을 (예) 로 선택 하셨습니다. 예약발송시간을 입력해주세요.");
			            return false;
			        }
			        
			        // 예약 문자 발송 입력 시간 현재시간과 비교 현재시간과 차이가 5분 이상 입력
			        var chkInterVal = Number(rsvtChrctrSndngYmd + rsvtChrctrSndngHr) - Number(date + time);
			        console.log("chkInterVal === " + chkInterVal);
			        if (chkInterVal < 5) {
			            util.Msg.alert(app, "현재일 예약문자발송일/시 를 설정시 최소 현재일시 보다 5분 이상 이후 로 설정해주세요. ");
			            return false;
			        }
			        
			    }
			    
			    // ### 05. 담당자 추가 여부 체크
			    var dsPicList = app.lookup("dsPicList"); // 담당자목록 데이터
			    console.log("담당자 목록 = " + dsTrprInfo.getRowCount());
			    if (dsPicList.getRowCount() == 0) {
			        util.Msg.alert(app, "행추가 버튼을 클릭하여 담당자를 \n선택해주세요.");
			        return false;
			    }
			    
			    // 담당자 그리드 필수 입력 항목 체크
			    if (!util.validate(app, "grdList")) return false;
			    
			    // 담당자 주담당자 여부 체크(담당자가 2명이상일 경우 주담당자 여부체크.)
			    var yCount = 0;
			    for (var i = 0; i < dsPicList.getRowCount(); i++) {
			        if (dsPicList.getValue(i, "PCHPRS_YN").toString() == "Y") {
			            yCount++;
			        }
			    }
			    
			    // 주담당자 예 체크
			    if (yCount == 0) {
			        util.Msg.alert(app, "추가하신 담당자에 주담당자여부 '예' 인  \n주담당자 1명은 필수 선택해주세요.");
			        return false;
			    } else if (yCount > 1) {
			        util.Msg.alert(app, "추가하신 담당자에 주담당자여부 '예' 인담당자가 1명 이상 입니다.  \n주담당자는 1명만 선택해주세요.");
			        return false;
			    }
			    
			    return true;
			}

