			/**
			 * 날짜, 시간 VALIDATE 체크
			 */
			function saveValidateCheck(){
			    var dti2 = app.lookup("dti2");
			    
			    var cmnTimeCombo2 = app.lookup("cmnTimeCombo2");
			    
			    if(dti2.value < moment().format("YYYYMMDD")){
			        util.Msg.alert(app, "예약일은 현재일과 같거나 커야합니다.", null, function(){
			            dti2.focus();
			        });
			        return false;
			    }
			    
			    if(dti2.value <= moment().format("YYYYMMDD") 
			        && cmnTimeCombo2.startTime < moment().format("HH") ){
			        util.Msg.alert(app, "예약시작시간(시)을 확인해주세요.", null, function(){
			             cmnTimeCombo2.focus();
			        });
			        return false; 
			    }
			    
			    if(dti2.value <= moment().format("YYYYMMDD") 
			        && cmnTimeCombo2.startTime <= moment().format("HH")
			        && cmnTimeCombo2.startMinute < moment().format("mm") ){
			        util.Msg.alert(app, "예약시작시간(분)을 확인해주세요", null, function(){
			             cmnTimeCombo2.focus();
			        });
			        return false; 
			    }
			    
			    if(dti2.value <= moment().format("YYYYMMDD") 
			        && cmnTimeCombo2.endTime <= moment().format("HH") 
			        && cmnTimeCombo2.endTime < cmnTimeCombo2.startTime){
			        util.Msg.alert(app, "예약종료시간(시)을 확인해주세요.", null, function(){
			             cmnTimeCombo2.focus();
			        });
			        return false; 
			    }
			    
			    if(dti2.value <= moment().format("YYYYMMDD") 
			        && cmnTimeCombo2.endTime <= cmnTimeCombo2.startTime 
			        && cmnTimeCombo2.endMinute <= cmnTimeCombo2.startMinute ){
			        util.Msg.alert(app, "예약종료시간(분)을 확인해주세요.", null, function(){
			             cmnTimeCombo2.focus();
			        });
			        return false; 
			    }
			    
			    return true;
			}

